window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-59316c88f45747f8"]={"versions": [{"id": "FIG-59316c88f45747f8", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Definition des Entwurfsmusters „Property Set Pattern without inheritance in {PropertySetClass}“ im Rahmen des AUTOSAR-Metamodells (Generic Structure Template). Dargestellt ist eine modellbasierte Transformationsbeziehung (<code>«transformation»</code>) von einem annotierten Ausgangsmodell (<code>annotated meta model</code>) in das transformierte Zielmetamodell (<code>extended meta model</code>) zur Realisierung von Variabilität über Eigenschaftsmengen ohne Vererbungshierarchien in der Eigenschaftsklasse.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich in zwei Namensräume (Pakete):</p>\n<ol class=\"fig-list\"><li><strong>annotated meta model</strong>:\n</li></ol>\n<ul class=\"fig-list\"><li><code>NonVariantSuperClass</code>: Basisklasse ohne Varianz.\n</li><li><code>{PropertySetClass}</code>: Spezialisierung von <code>NonVariantSuperClass</code> mit dem Stereotyp <code>«atpVariation»</code>. Enthält das variierende Attribut <code>+ {attr}: {Type}</code> (rot markiert).\n</li><li><code>AggreatedClass</code>: Wird von <code>{PropertySetClass}</code> per Komposition mit Rollenname <code>+{aggregated}</code> und Kardinalität <code>{n}</code> aggregiert.\n</li></ul>\n<ol class=\"fig-list\"><li><strong>extended meta model</strong>:\n</li></ol>\n<ul class=\"fig-list\"><li><code>NonVariantSuperClass</code>: Unveränderte Basisklasse.\n</li><li><code>{PropertySetClass}</code>: Spezialisierung von <code>NonVariantSuperClass</code>. Hält eine Komposition mit Rolle <code>+{propertySetClass}Conditional</code> und Multiplizität <code>1..*</code> auf <code>{PropertySetClass}Conditional</code>.\n</li><li><code>{PropertySetClass}Conditional</code> (grün hervorgehoben): Repräsentiert die bedingte Ausprägung. Realisiert eine Generalisierung auf <code>{PropertySetClass}Content</code> und aggregiert per Komposition die Zielklasse <code>VariationPoint</code> mit Rollenname <code>+variationPoint</code> und Kardinalität <code>0..1</code>.\n</li><li><code>{PropertySetClass}Content</code> (grün hervorgehoben): Trägt das optionale Attribut <code>+ {attr}: {Type} [0..1]</code> und hält eine Komposition auf <code>AggregatedClass</code> mit Rollenname <code>+{aggregated}</code> und Multiplizität <code>0..{n}</code>.\n</li><li><code>AggregatedClass</code>: Zielklasse der transformierten Inhaltsaggregation.\n</li></ul>\n<p class=\"fig-p\">Zwischen beiden Paketen verbindet ein gestrichelter Abhängigkeitspfeil mit dem Stereotyp <code>«transformation»</code> das annotierte Modell mit dem erweiterten Modell.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne Laufzeitsequenzen. Die Transformation überführt ein kompaktes, mit Varianzstereotyp annotiertes Klassenschema in eine explizite Auflösung: Anstelle einer direkten Aggregation von Attributen und Klassen mit fester Kardinalität <code>{n}</code> erzeugt die Transformation eine 1..*-Menge bedingter Ausprägungen (<code>{PropertySetClass}Conditional</code>), die jeweils über einen <code>VariationPoint</code> verfügen und deren gemeinsame Eigenschaften im abgeleiteten <code>{PropertySetClass}Content</code> mit aufgeweichter Multiplizität (<code>0..{n}</code> bzw. <code>[0..1]</code>) gekapselt werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Muster definiert die formale Metamodell-Regel für Werkzeuge zur Verarbeitung von AUTOSAR-Schablonen, wenn Eigenschaften einer Klasse variieren dürfen, ohne dass Vererbung innerhalb des Eigenschaftssets zum Einsatz kommt. Rollennamen und Klassennamen in geschweiften Klammern (<code>{...}</code>) stellen generische Platzhalter dar. Rot gekennzeichnete Elemente im Quellmodell markieren die varianzbehafteten Merkmale; grün gefärbte Klassen im Zielmodell repräsentieren die durch die Metamodell-Transformation synthetisierten Artefakte zur Variantenhandhabung.</p>"}, {"id": "FIG-e851728b70741824", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Definition des Entwurfsmusters „Property Set Pattern without inheritance in {PropertySetClass}“ im Rahmen des AUTOSAR-Metamodells (Generic Structure Template). Dargestellt ist eine modellbasierte Transformationsbeziehung (<code>«transformation»</code>) von einem annotierten Ausgangsmodell (<code>annotated meta model</code>) in das transformierte Zielmetamodell (<code>extended meta model</code>) zur Realisierung von Variabilität über Eigenschaftsmengen ohne Vererbungshierarchien in der Eigenschaftsklasse.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich in zwei Namensräume (Pakete):</p>\n<ol class=\"fig-list\"><li><strong>annotated meta model</strong>:\n</li></ol>\n<ul class=\"fig-list\"><li><code>NonVariantSuperClass</code>: Basisklasse ohne Varianz.\n</li><li><code>{PropertySetClass}</code>: Spezialisierung von <code>NonVariantSuperClass</code> mit Stereotyp <code>«atpVariation»</code>. Enthält das variierende Attribut <code>+ {attr} :{Type}</code> (rot markiert) sowie ein Tag-Fach <code>tags</code> mit dem Eintrag <code>vh.latestBindingTime =</code>.\n</li><li><code>AggreatedClass</code>: Wird von <code>{PropertySetClass}</code> per Komposition mit Rollenname <code>+{aggregated}</code> und Kardinalität <code>{n}</code> aggregiert.\n</li></ul>\n<ol class=\"fig-list\"><li><strong>extended meta model</strong>:\n</li></ol>\n<ul class=\"fig-list\"><li><code>NonVariantSuperClass</code>: Unveränderte Basisklasse.\n</li><li><code>{PropertySetClass}</code>: Spezialisierung von <code>NonVariantSuperClass</code>. Hält eine Komposition mit Rolle <code>+{propertySetClass}Conditional</code> und Multiplizität <code>1..*</code> auf <code>{PropertySetClass}Conditional</code>.\n</li><li><code>{PropertySetClass}Conditional</code> (grün hervorgehoben): Generalisiert <code>{PropertySetClass}Content</code> und aggregiert per Komposition <code>VariationPoint</code> (Rolle <code>+variationPoint</code>, Kardinalität <code>0..1</code>). Die Kompositionskante ist mit der OCL-Bedingung <code>{VariationPoint.ConditionByFormula.bindingTime &lt;= &lt;&lt;atpVariation&gt;&gt;.vh.latestBindingTime}</code> annotiert.\n</li><li><code>{PropertySetClass}Content</code> (grün hervorgehoben): Trägt das Attribut <code>+ {attr} :{Type} [0..1]</code> und hält eine Komposition auf <code>AggregatedClass</code> mit Rolle <code>+{aggregated}</code> und Kardinalität <code>0..{n}</code>.\n</li><li><code>AggregatedClass</code>: Zielklasse der transformierten Inhaltsaggregation.\n</li></ul>\n<p class=\"fig-p\">Zwischen beiden Paketen verbindet ein gestrichelter Pfeil mit dem Stereotyp <code>«transformation»</code>.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne Laufzeitsequenzen. Die Transformation überführt ein kompaktes, mit Varianzstereotyp annotiertes Klassenschema in eine explizite Auflösung: Anstelle einer direkten Aggregation von Attributen und Klassen mit fester Kardinalität <code>{n}</code> erzeugt die Transformation eine 1..*-Menge bedingter Ausprägungen (<code>{PropertySetClass}Conditional</code>), die jeweils über einen <code>VariationPoint</code> verfügen und deren gemeinsame Eigenschaften im abgeleiteten <code>{PropertySetClass}Content</code> mit aufgeweichter Multiplizität (<code>0..{n}</code> bzw. <code>[0..1]</code>) gekapselt werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Muster definiert die formale Metamodell-Regel für AUTOSAR-Entwicklungswerkzeuge zur Transformation von Variabilität ohne Vererbung in <code>{PropertySetClass}</code>. Die im annotierten Modell spezifizierte späteste Bindezeit (<code>vh.latestBindingTime</code>) schränkt über die OCL-Invariante <code>{VariationPoint.ConditionByFormula.bindingTime &lt;= &lt;&lt;atpVariation&gt;&gt;.vh.latestBindingTime}</code> die zulässigen Bindezeiten der Formelbedingungen am synthetisierten Variationspunkt normativ ein. Rot markierte Elemente definieren Eingangsmerkmale mit Varianz, grün markierte Elemente zeigen die generierten Zielstrukturen.</p>"}, {"id": "FIG-986a0e5042aef8ea", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Definition des Entwurfsmusters „Property Set Pattern without inheritance in {PropertySetClass}“ im Rahmen des AUTOSAR-Metamodells (Generic Structure Template). Dargestellt ist eine modellbasierte Transformationsbeziehung (<code>«transformation»</code>) von einem annotierten Ausgangsmodell (<code>annotated meta model</code>) in das transformierte Zielmetamodell (<code>extended meta model</code>) zur Realisierung von Variabilität über Eigenschaftsmengen ohne Vererbungshierarchien in der Eigenschaftsklasse.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich in zwei Namensräume (Pakete):</p>\n<ol class=\"fig-list\"><li><strong>annotated meta model</strong>:\n</li></ol>\n<ul class=\"fig-list\"><li><code>NonVariantSuperClass</code>: Basisklasse ohne Varianz.\n</li><li><code>{PropertySetClass}</code>: Spezialisierung von <code>NonVariantSuperClass</code> mit Stereotyp <code>«atpVariation»</code>. Enthält das Attribut <code>+ {attr} :{Type}</code> (rot markiert) und das Tag-Fach <code>tags</code> mit <code>vh.latestBindingTime =</code>.\n</li><li><code>AggreatedClass</code>: Komposition von <code>{PropertySetClass}</code> mit Rolle <code>+{aggregated}</code> und Kardinalität <code>{n}</code>.\n</li></ul>\n<ol class=\"fig-list\"><li><strong>extended meta model</strong>:\n</li></ol>\n<ul class=\"fig-list\"><li><code>NonVariantSuperClass</code>: Basisklasse.\n</li><li><code>{PropertySetClass}</code>: Spezialisierung von <code>NonVariantSuperClass</code>. Besitzt eine Komposition mit Rolle <code>+{propertySetClass}Conditional</code> (Multiplizität <code>1..*</code>) auf <code>{PropertySetClass}Conditional</code>.\n</li><li><code>{PropertySetClass}Conditional</code> (grün hervorgehoben): Erbt via Generalisierung von <code>{PropertySetClass}Content</code> und aggregiert per Komposition <code>VariantHandling::VariationPoint</code> (Rolle <code>+variationPoint</code>, Kardinalität <code>0..1</code>). Die Assoziationslinie ist mit der OCL-Bedingung <code>{VariationPoint.ConditionByFormula.bindingTime &lt;= &lt;&lt;atpVariation&gt;&gt;.vh.latestBindingTime}</code> versehen.\n</li><li><code>VariantHandling::VariationPoint</code> (grün hervorgehoben): Paketqualifizierte Variationspunktklasse mit dem Attribut <code>+ shortLabel :Identifier [0..1]</code>.\n</li><li><code>{PropertySetClass}Content</code> (grün hervorgehoben): Enthält <code>+ {attr} :{Type} [0..1]</code> und aggregiert <code>AggregatedClass</code> mit Rolle <code>+{aggregated}</code> und Multiplizität <code>0..{n}</code>.\n</li><li><code>AggregatedClass</code>: Aggregierte Zielklasse.\n</li></ul>\n<p class=\"fig-p\">Zwischen den Paketen besteht die gerichtete Transformationsbeziehung <code>«transformation»</code>.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne Laufzeitsequenzen. Die Transformation überführt ein kompaktes, mit Varianzstereotyp annotiertes Klassenschema in eine explizite Auflösung: Anstelle einer direkten Aggregation von Attributen und Klassen mit fester Kardinalität <code>{n}</code> erzeugt die Transformation eine 1..*-Menge bedingter Ausprägungen (<code>{PropertySetClass}Conditional</code>), die jeweils über einen <code>VariationPoint</code> verfügen und deren gemeinsame Eigenschaften im abgeleiteten <code>{PropertySetClass}Content</code> mit aufgeweichter Multiplizität (<code>0..{n}</code> bzw. <code>[0..1]</code>) gekapselt werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Entwurfsmuster bindet die Variantenhandhabung normativ an das Paket <code>VariantHandling</code> und dessen Element <code>VariationPoint</code>. Dieses stellt über das optionale Attribut <code>shortLabel</code> vom Typ <code>Identifier</code> eine Identifikationsmöglichkeit für die jeweilige Bedingungsausprägung bereit. Werkzeuge müssen sicherstellen, dass die Bindezeit der Formelbedingung am Variationspunkt die an <code>«atpVariation»</code> deklarierte Bindezeitgrenze (<code>vh.latestBindingTime</code>) nicht überschreitet.</p>"}, {"id": "FIG-5d440f20ec2d3c6e", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Definition des Entwurfsmusters „Property Set Pattern without inheritance in {PropertySetClass}“ im Rahmen des AUTOSAR-Metamodells (Generic Structure Template). Dargestellt ist eine modellbasierte Transformationsbeziehung (<code>«transformation»</code>) von einem annotierten Ausgangsmodell (<code>annotated meta model</code>) in das transformierte Zielmetamodell (<code>extended meta model</code>) zur Realisierung von Variabilität über Eigenschaftsmengen ohne Vererbungshierarchien in der Eigenschaftsklasse.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich in zwei Namensräume (Pakete):</p>\n<ol class=\"fig-list\"><li><strong>annotated meta model</strong>:\n</li></ol>\n<ul class=\"fig-list\"><li><code>NonVariantSuperClass</code>: Basisklasse ohne Varianz.\n</li><li><code>{PropertySetClass}</code>: Spezialisierung von <code>NonVariantSuperClass</code> mit Stereotyp <code>«atpVariation»</code>. Enthält das Attribut <code>+ {attr} :{Type}</code> (rot markiert) und das Tag-Fach <code>tags</code> mit <code>vh.latestBindingTime =</code>.\n</li><li><code>AggreatedClass</code>: Komposition von <code>{PropertySetClass}</code> mit Rolle <code>+{aggregated}</code> und Kardinalität <code>{n}</code>.\n</li></ul>\n<ol class=\"fig-list\"><li><strong>extended meta model</strong>:\n</li></ol>\n<ul class=\"fig-list\"><li><code>NonVariantSuperClass</code>: Basisklasse.\n</li><li><code>{PropertySetClass}</code>: Spezialisierung von <code>NonVariantSuperClass</code>. Besitzt eine Komposition mit Rolle <code>+{propertySetClass}Conditional</code> (Multiplizität <code>1..*</code>) auf <code>{PropertySetClass}Conditional</code>.\n</li><li><code>{PropertySetClass}Conditional</code> (grün hervorgehoben): Erbt via Generalisierung von <code>{PropertySetClass}Content</code> und aggregiert per Komposition <code>VariantHandling::VariationPoint</code> (Rolle <code>+variationPoint</code>, Kardinalität <code>0..1</code>). Die Assoziationslinie ist mit der OCL-Bedingung <code>{VariationPoint.ConditionByFormula.bindingTime &lt;= &lt;&lt;atpVariation&gt;&gt;.vh.latestBindingTime}</code> versehen.\n</li><li><code>VariantHandling::VariationPoint</code> (grün hervorgehoben): Paketqualifizierte Variationspunktklasse mit dem Attribut <code>+ shortLabel :Identifier [0..1]</code>.\n</li><li><code>{PropertySetClass}Content</code> (grün hervorgehoben): Enthält <code>+ {attr} :{Type} [0..1]</code> und aggregiert <code>AggregatedClass</code> mit Rolle <code>+{aggregated}</code> und Multiplizität <code>0..{n}</code>.\n</li><li><code>AggregatedClass</code>: Aggregierte Zielklasse.\n</li></ul>\n<p class=\"fig-p\">Zwischen den Paketen besteht die gerichtete Transformationsbeziehung <code>«transformation»</code>.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne Laufzeitsequenzen. Die Transformation überführt ein kompaktes, mit Varianzstereotyp annotiertes Klassenschema in eine explizite Auflösung: Anstelle einer direkten Aggregation von Attributen und Klassen mit fester Kardinalität <code>{n}</code> erzeugt die Transformation eine 1..*-Menge bedingter Ausprägungen (<code>{PropertySetClass}Conditional</code>), die jeweils über einen <code>VariationPoint</code> verfügen und deren gemeinsame Eigenschaften im abgeleiteten <code>{PropertySetClass}Content</code> mit aufgeweichter Multiplizität (<code>0..{n}</code> bzw. <code>[0..1]</code>) gekapselt werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Entwurfsmuster bindet die Variantenhandhabung normativ an das Paket <code>VariantHandling</code> und dessen Element <code>VariationPoint</code>. Dieses stellt über das optionale Attribut <code>shortLabel</code> vom Typ <code>Identifier</code> eine Identifikationsmöglichkeit für die jeweilige Bedingungsausprägung bereit. Werkzeuge müssen sicherstellen, dass die Bindezeit der Formelbedingung am Variationspunkt die an <code>«atpVariation»</code> deklarierte Bindezeitgrenze (<code>vh.latestBindingTime</code>) nicht überschreitet.</p>"}, {"id": "FIG-8350d30fa17524f1", "releases": ["R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Definition des Entwurfsmusters „Property Set Pattern without inheritance in {PropertySetClass}“ im Rahmen des AUTOSAR-Metamodells (Generic Structure Template). Dargestellt ist eine modellbasierte Transformationsbeziehung (<code>«transformation»</code>) von einem annotierten Ausgangsmodell (<code>annotated meta model</code>) in das transformierte Zielmetamodell (<code>extended meta model</code>) zur Realisierung von Variabilität über Eigenschaftsmengen ohne Vererbungshierarchien in der Eigenschaftsklasse.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich in zwei Namensräume (Pakete):</p>\n<ol class=\"fig-list\"><li><strong>annotated meta model</strong>:\n</li></ol>\n<ul class=\"fig-list\"><li><code>NonVariantSuperClass</code>: Basisklasse ohne Varianz.\n</li><li><code>{PropertySetClass}</code>: Spezialisierung von <code>NonVariantSuperClass</code> mit Stereotyp <code>«atpVariation»</code>. Enthält das variierende Attribut <code>+ {attr}: {Type}</code> (rot markiert) sowie das Tag-Fach <code>tags</code> mit <code>vh.latestBindingTime =</code>.\n</li><li><code>AggreatedClass</code>: Komposition von <code>{PropertySetClass}</code> mit Rolle <code>+{aggregated}</code> und Kardinalität <code>{n}</code>.\n</li></ul>\n<ol class=\"fig-list\"><li><strong>extended meta model</strong>:\n</li></ol>\n<ul class=\"fig-list\"><li><code>NonVariantSuperClass</code>: Basisklasse.\n</li><li><code>{PropertySetClass}</code>: Spezialisierung von <code>NonVariantSuperClass</code>. Hält eine Komposition mit Rolle <code>+{propertySetClass}Conditional</code> (Multiplizität <code>1..*</code>) auf <code>{PropertySetClass}Conditional</code>.\n</li><li><code>{PropertySetClass}Conditional</code> (grün hervorgehoben): Generalisiert <code>{PropertySetClass}Content</code> und aggregiert per Komposition <code>VariantHandling::VariationPoint</code> (Rolle <code>+variationPoint</code>, Multiplizität <code>0..1</code>), versehen mit der OCL-Bedingung <code>{VariationPoint.ConditionByFormula.bindingTime &lt;= &lt;&lt;atpVariation&gt;&gt;.vh.latestBindingTime}</code>.\n</li><li><code>VariantHandling::VariationPoint</code> (grün hervorgehoben): Paketqualifizierte Variationspunktklasse mit dem Attribut <code>+ shortLabel: Identifier [0..1]</code>.\n</li><li><code>{PropertySetClass}Content</code> (grün hervorgehoben): Enthält <code>+ {attr}: {Type} [0..1]</code> und aggregiert <code>AggregatedClass</code> mit Rolle <code>+{aggregated}</code> und Multiplizität <code>0..{n}</code>.\n</li><li><code>AggregatedClass</code>: Aggregierte Zielklasse.\n</li></ul>\n<p class=\"fig-p\">Zwischen beiden Paketen verläuft die Transformationsbeziehung <code>«transformation»</code>.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne Laufzeitsequenzen. Die Transformation überführt ein kompaktes, mit Varianzstereotyp annotiertes Klassenschema in eine explizite Auflösung: Anstelle einer direkten Aggregation von Attributen und Klassen mit fester Kardinalität <code>{n}</code> erzeugt die Transformation eine 1..*-Menge bedingter Ausprägungen (<code>{PropertySetClass}Conditional</code>), die jeweils über einen <code>VariationPoint</code> verfügen und deren gemeinsame Eigenschaften im abgeleiteten <code>{PropertySetClass}Content</code> mit aufgeweichter Multiplizität (<code>0..{n}</code> bzw. <code>[0..1]</code>) gekapselt werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Entwurfsmuster bindet die Variantenhandhabung normativ an das Paket <code>VariantHandling</code> und dessen Element <code>VariationPoint</code>. Dieses stellt über das optionale Attribut <code>shortLabel</code> vom Typ <code>Identifier</code> eine Identifikationsmöglichkeit für die jeweilige Bedingungsausprägung bereit. Werkzeuge müssen sicherstellen, dass die Bindezeit der Formelbedingung am Variationspunkt die an <code>«atpVariation»</code> deklarierte Bindezeitgrenze (<code>vh.latestBindingTime</code>) nicht überschreitet.</p>"}, {"id": "FIG-1c5ba7f556e3a5ab", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Definition des Entwurfsmusters „Property Set Pattern without inheritance in {PropertySetClass}“ im Rahmen des AUTOSAR-Metamodells (Generic Structure Template). Dargestellt ist eine modellbasierte Transformationsbeziehung (<code>«transformation»</code>) von einem annotierten Ausgangsmodell (<code>annotated meta model</code>) in das transformierte Zielmetamodell (<code>extended meta model</code>) zur Realisierung von Variabilität über Eigenschaftsmengen ohne Vererbungshierarchien in der Eigenschaftsklasse.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich in zwei Namensräume (Pakete):</p>\n<ol class=\"fig-list\"><li><strong>annotated meta model</strong>:\n</li></ol>\n<ul class=\"fig-list\"><li><code>NonVariantSuperClass</code>: Basisklasse ohne Varianz.\n</li><li><code>{PropertySetClass}</code>: Spezialisierung von <code>NonVariantSuperClass</code> mit Stereotyp <code>«atpVariation»</code>. Enthält das variierende Attribut <code>+ {attr}: {Type}</code> (rot markiert) sowie das Tag-Fach <code>tags</code> mit <code>vh.latestBindingTime =</code>.\n</li><li><code>AggreatedClass</code>: Komposition von <code>{PropertySetClass}</code> mit Rolle <code>+{aggregated}</code> und Kardinalität <code>{n}</code>.\n</li></ul>\n<ol class=\"fig-list\"><li><strong>extended meta model</strong>:\n</li></ol>\n<ul class=\"fig-list\"><li><code>NonVariantSuperClass</code>: Basisklasse.\n</li><li><code>{PropertySetClass}</code>: Spezialisierung von <code>NonVariantSuperClass</code>. Hält eine Komposition mit Rolle <code>+{propertySetClass}Conditional</code> (Multiplizität <code>1..*</code>) auf <code>{PropertySetClass}Conditional</code>.\n</li><li><code>{PropertySetClass}Conditional</code> (grün hervorgehoben): Generalisiert <code>{PropertySetClass}Content</code> und aggregiert per Komposition <code>VariantHandling::VariationPoint</code> (Rolle <code>+variationPoint</code>, Multiplizität <code>0..1</code>), versehen mit der OCL-Bedingung <code>{VariationPoint.ConditionByFormula.bindingTime &lt;= &lt;&lt;atpVariation&gt;&gt;.vh.latestBindingTime}</code>.\n</li><li><code>VariantHandling::VariationPoint</code> (grün hervorgehoben): Paketqualifizierte Variationspunktklasse mit dem Attribut <code>+ shortLabel: Identifier [0..1]</code>.\n</li><li><code>{PropertySetClass}Content</code> (grün hervorgehoben): Enthält <code>+ {attr}: {Type} [0..1]</code> und aggregiert <code>AggregatedClass</code> mit Rolle <code>+{aggregated}</code> und Multiplizität <code>0..{n}</code>.\n</li><li><code>AggregatedClass</code>: Aggregierte Zielklasse.\n</li></ul>\n<p class=\"fig-p\">Zwischen beiden Paketen verläuft die Transformationsbeziehung <code>«transformation»</code>.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne Laufzeitsequenzen. Die Transformation überführt ein kompaktes, mit Varianzstereotyp annotiertes Klassenschema in eine explizite Auflösung: Anstelle einer direkten Aggregation von Attributen und Klassen mit fester Kardinalität <code>{n}</code> erzeugt die Transformation eine 1..*-Menge bedingter Ausprägungen (<code>{PropertySetClass}Conditional</code>), die jeweils über einen <code>VariationPoint</code> verfügen und deren gemeinsame Eigenschaften im abgeleiteten <code>{PropertySetClass}Content</code> mit aufgeweichter Multiplizität (<code>0..{n}</code> bzw. <code>[0..1]</code>) gekapselt werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Entwurfsmuster bindet die Variantenhandhabung normativ an das Paket <code>VariantHandling</code> und dessen Element <code>VariationPoint</code>. Dieses stellt über das optionale Attribut <code>shortLabel</code> vom Typ <code>Identifier</code> eine Identifikationsmöglichkeit für die jeweilige Bedingungsausprägung bereit. Werkzeuge müssen sicherstellen, dass die Bindezeit der Formelbedingung am Variationspunkt die an <code>«atpVariation»</code> deklarierte Bindezeitgrenze (<code>vh.latestBindingTime</code>) nicht überschreitet.</p>"}], "trans": [{"from": "FIG-59316c88f45747f8", "to": "FIG-e851728b70741824", "fr": "R4.0.3", "tr": "R4.1.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Im Paket <code>annotated meta model</code> erhält die Klasse <code>{PropertySetClass}</code> das Tag-Fach <code>tags</code> mit dem Tag-Eintrag <code>vh.latestBindingTime =</code>.\n</li><li>Im Paket <code>extended meta model</code> wird an der Aggregation von <code>{PropertySetClass}Conditional</code> zu <code>VariationPoint</code> eine OCL-Bedingung ergänzt: <code>{VariationPoint.ConditionByFormula.bindingTime &lt;= &lt;&lt;atpVariation&gt;&gt;.vh.latestBindingTime}</code>.\n</li></ul>"}, {"from": "FIG-e851728b70741824", "to": "FIG-986a0e5042aef8ea", "fr": "R4.1.3", "tr": "R4.2.2", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Die Zielklasse der Komposition <code>+variationPoint</code> im Paket <code>extended meta model</code> wird von <code>VariationPoint</code> zu <code>VariantHandling::VariationPoint</code> qualifiziert.\n</li><li><code>VariantHandling::VariationPoint</code> erhält das Attribut <code>+ shortLabel :Identifier [0..1]</code> und wird grün hervorgehoben dargestellt.\n</li></ul>"}, {"from": "FIG-986a0e5042aef8ea", "to": "FIG-5d440f20ec2d3c6e", "fr": "R4.2.2", "tr": "R4.3.1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-5d440f20ec2d3c6e", "to": "FIG-8350d30fa17524f1", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Im Paket <code>annotated meta model</code> wird in der Klasse <code>{PropertySetClass}</code> das Leerzeichen vor dem Doppelpunkt im Attribut <code>+ {attr}: {Type}</code> entfernt.\n</li><li>Im Paket <code>extended meta model</code> wird in der Klasse <code>{PropertySetClass}Content</code> das Leerzeichen vor dem Doppelpunkt im Attribut <code>+ {attr}: {Type} [0..1]</code> entfernt.\n</li><li>Im Paket <code>extended meta model</code> wird in der Klasse <code>VariantHandling::VariationPoint</code> das Leerzeichen vor dem Doppelpunkt im Attribut <code>+ shortLabel: Identifier [0..1]</code> entfernt.\n</li></ul>"}, {"from": "FIG-8350d30fa17524f1", "to": "FIG-1c5ba7f556e3a5ab", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
